package com.slime;
import android.app.Activity; import android.graphics.Color; import android.graphics.Typeface; import android.graphics.drawable.GradientDrawable; import android.os.Bundle;
import android.view.View; import android.view.ViewGroup; import android.widget.Button; import android.widget.LinearLayout; import android.widget.ScrollView; import android.widget.TextView;
import java.util.ArrayList;
public class GuideActivity extends Activity {
 LinearLayout col; float d;
 final ArrayList<TextView> heads=new ArrayList<TextView>(), bodies=new ArrayList<TextView>(), titles=new ArrayList<TextView>();
 @Override protected void onCreate(Bundle b){
  super.onCreate(b);
  d=getResources().getDisplayMetrics().density; int pad=(int)(16*d);
  ScrollView sv=new ScrollView(this); sv.setBackgroundColor(Color.parseColor("#1B2631"));
  col=new LinearLayout(this); col.setOrientation(LinearLayout.VERTICAL); col.setPadding(pad,pad,pad,pad*2);
  sv.addView(col,new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));
  text("SlimeDroid guide",22f,"#FFFFFF",true,0);
  text("Everything about the app, from the very beginning to the end. Tap a title to open it.",13f,"#AEB6BF",false,4);
  LinearLayout row=new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL);
  row.addView(btn("Open all",true)); row.addView(btn("Close all",false)); col.addView(row);

  sec("1. What is SlimeDroid?",
   "SlimeDroid is a little blue slime that lives on top of your other apps.\n\n- It reacts to what you do: charging, headphones, shaking, unlocking, night time.\n- It chats with you like a friend and remembers things you tell it.\n- It can read what is on your screen and talk about it.\n- With Shizuku and Termux it can press buttons, swipe, open apps, change settings and take screenshots for you.\n- It grows up through eight tiers with hats, glasses, a crown, auras and shields, earning XP from real chats, voice, tasks and streaks - plus 14 achievements.\n\nIt is built to cost nothing: it uses OpenRouter's free AI models.");

  sec("2. Quick start (about 5 minutes)",
   "Do these on the home screen of this app, in order:\n\n1. Tap 'Allow overlay' and switch it on. This lets the slime float over other apps.\n2. Tap 'Allow accessibility' and switch on SlimeDroid. This is the slime's eyes and hands.\n3. Tap 'Allow notifications' and switch on SlimeDroid. This lets it see your notifications.\n4. Tap 'Allow battery unrestricted' and say yes, so Android does not put it to sleep.\n5. Get a free OpenRouter key: open openrouter.ai, make an account, go to Keys, create a key and copy it. Paste it in the key box on the home screen and tap 'Add key'.\n6. Tap 'Start slime'. A slime appears in the middle of the screen.\n7. Long-press the slime to open the chat, and say hi.\n\nThe checklist at the top of the home screen shows a tick next to everything that is ready.");

  sec("3. What each permission does",
   "Overlay: draws the slime on top of other apps. Without it nothing shows.\n\nAccessibility: lets the slime read the text on your screen and tap, type and scroll when you ask. It is the 'See' button and the 'open', 'tap', 'type', 'scroll' commands. The slime tries to stay out of private apps like banking.\n\nNotification access: lets it read incoming notifications so it can show 'ping from...' bubbles and summarise them when you say 'catch me up'.\n\nBattery unrestricted: stops Android from killing the slime in the background.\n\nRun commands in Termux: lets SlimeDroid ask Termux to run phone commands (see section 13).\n\nMicrophone: used only for the listening feature (section 19), only while the screen is on and only after you turn it on. Recorded speech goes to Android's on-device speech recognizer, not to OpenRouter.\n\nNothing is sent anywhere except to the AI provider you switched on - OpenRouter or Google's Gemini - when you chat, when it peeks at your screen, or when you use 'look'.");

  sec("4. The free AI providers and the daily limits",
   "SlimeDroid can talk through TWO free cloud providers, both with rotating key pools: OpenRouter (the default) and Google AI Studio's Gemini, which is usually the fastest to reply. A third, fully offline option runs on the phone itself with no key at all - see section 20.\n\nOpenRouter's free plan allows about 50 requests a day (and 20 a minute) for each OpenRouter account. Google no longer publishes fixed Gemini free-tier numbers: each Google Cloud project has its own limits shown in AI Studio's rate-limit page, they reset around midnight US Pacific time, and the full flash models (2.5 through 3.x) sit at roughly 20 requests a day on free projects, while the flash-lite models keep a much larger allowance (about 500 a day) - so SlimeDroid defaults to flash-lite. Google retires model names for new projects over time: gemini-2.5-flash-lite now answers 404 on new projects, which is why the default is gemini-3.5-flash-lite, and the app automatically walks its fallback list (3.5-lite, 3.1-lite, then the older 2.5 names that still work on older projects) to a model the key can actually use. Quotas are counted per Google project, not per key: several keys from the same account share one pool, only keys from different Google accounts add real room.\n\n- Every chat message you send uses 1 request on whichever provider is active.\n- The slime's own unprompted things (random chat, peeks, humming songs) are capped locally and, while Gemini is selected, they run through OpenRouter instead so your small Gemini daily pool is spent only on your own messages.\n- Per-minute bursts (RPM) are retried automatically after a short wait and never bench a key for the day; only the genuine daily quota does. 'gemini key reset' (and 'key reset' for OpenRouter) clears any parked-key marks by hand, and the real Google error text is shown when a request is refused.\n- Type 'status' or 'ai provider' to see the active provider, today's request count and the model in use. The denominator is no longer guessed - Google sets the per-project limit, visible in AI Studio.\n- Switch any time with 'use gemini' or 'use openrouter', or just tap the AI button at the start of the quick-action row in the chat (green for Gemini, blue for OpenRouter, purple for offline; on 32-bit phones offline is skipped automatically). The choice is saved; each provider keeps its own keys, quota counters and dead-key list.\n- Add several keys per provider: when one is rejected or runs out of free quota, the slime switches to the next by itself. Get Gemini keys free at aistudio.google.com/apikey (or the home screen) and OpenRouter keys at openrouter.ai/keys.\n- 'gemini models' lists what your Gemini key can use, 'gemini model NAME' pins one (default gemini-3.5-flash-lite, with gemini-3.1-flash-lite as automatic backup; pin a full flash model only when you need the smarter one and have daily room - its free allowance is only about 20), 'gemini model reset' restores it. 'gemini diagnose' runs one test call and prints the raw HTTP code, Google's full response and parse result - use it whenever replies come back empty. 'look' screenshot questions work through Gemini too, with OpenRouter as automatic backup. On 2.5 models 'thinking' is switched off in requests so it can't eat the whole reply; 3.x lite already defaults to minimal thinking.\n\nFor OpenRouter the app keeps a live list of free ':free' models (refreshed every 12 hours) and rotates through them message by message, so no single model's daily quota burns out; if the list is empty it falls back to the 'openrouter/free' router. 'models' lists the free models right now and shows which one served the last reply, 'model NAME' pins one model, and 'model reset' goes back to automatic rotation.");

  sec("5. Using more than one key",
   "You can add several keys per provider. When one stops working (rejected, out of credit, or out of free messages for the day) the slime switches to the next one by itself.\n\nOpenRouter commands: 'keys' shows them (masked), 'key add KEY', 'key remove N', 'key next'. Gemini commands: 'gemini keys', 'gemini key add KEY', 'gemini key remove N', 'gemini key next'. Both pools can also be managed on the home screen, and both are stored separately so switching providers never mixes them up.\n\nImportant: keys that belong to the same account share one limit. Only keys from different accounts add more room. Follow each provider's own rules when you make accounts. Never paste a key into a chat message expecting the slime to remember it as conversation - use the key commands or the home screen boxes instead.");

  sec("6. Meeting your slime",
   "Gestures:\n- Tap: its mood changes and it dashes away.\n- Poke it 4 times quickly: it gets annoyed.\n- Drag: move it anywhere (it stays inside the screen).\n- Long-press: open or close the chat.\n- Double-tap: close the slime. Open the app and tap 'Start slime' to bring it back.\n\nIt has needs: food, energy and joy. Feed it with 'feed', play with 'play', and 'status' shows the numbers. When it is hungry, sleepy or sad it tells you. It sleeps at night (before 6 am) unless you say 'wake up'.\n\nMoods: Happy, Sleepy, Mad, Love, Hungry, Cry, Wow, Wink and Dead. They change its face and color. It also runs when it moves and walks around by itself.");

  sec("7. The chat window",
   "Long-press the slime to open it. Type in the box and press Enter or 'Send'. The chat lifts above the keyboard while you type.\n\nButtons: Send, See (read my screen), TTS (voice on and off), Hist (history), X (close). Quick buttons: Feed, Play, Clip, Catch up, Shh, Status, Cmds.\n\nCopying: long-press any message to copy it. Code boxes have a Copy button. Type 'copy' to copy the last reply, or 'copy all' for the whole chat.\n\nLong replies fold into a card: tap it to open or close. Code gets its own box with the language, the line count, Copy and Collapse.\n\nMath: when the slime writes LaTeX it is drawn as real math. It needs internet the first time. Offline you see the plain text.\n\nThe speech bubble above the slime shows a short version of what it says.");

  sec("8. Memory",
   "The slime remembers things you tell it, one fact at a time.\n\n- It picks facts up from what you say (your name, school, projects, likes, plans, people you mention) and from tags the AI adds for free.\n- 'remember I have an exam on Friday' saves something on purpose. If that fact changes, tell it again - the old wording is kept as '(was: ...)' and it even says 'you used to say...' when you update it.\n- 'memories' shows everything, numbered. 'remember about school' (or 'memory search school') finds memories on a topic, and 'memory change 3 new wording' rewords one. 'forget 3' removes one, 'forget all' wipes everything.\n- 'what do you remember' gives a short summary. 'memory off' stops automatic saving, 'memory on' turns it back on.\n- Memories age: a one-off fact never repeated slowly loses importance after a month, while things you repeat and identity facts stay strong. Recall weights identity, people and plans and uses word pairs, so short names and different phrasing still match.\n- 'memory export' writes a dated backup of memories, chats and notifications to /sdcard/SlimePouch/backups (it survives uninstalls and factory resets of app data). 'memory import' restores the newest one, or 'memory import FILE' a specific file; duplicates merge automatically. Without Shizuku a fallback copy is saved in the app's external folder instead.\n\nIt does not keep passwords, PINs, codes, card or long ID numbers, email addresses, or some very sensitive topics.\n\nMemories are stored on your phone. The ones that fit the moment are sent to the AI along with your message so it can use them.");

  sec("9. Looking at your screen",
   "'See' or a question like 'what do you think of this?' lets the slime read the text on your screen (needs accessibility).\n\nRandom peeks: now and then (about every 45 minutes when you are using the phone) it glances at your screen and says what it thinks. 'peek' does it now, 'peek off' stops it, 'peek more' and 'peek less' change how often. It skips private-looking screens and stays quiet in focus and game mode.\n\n'look what is this?' takes a real screenshot and asks a vision AI about it (needs Shizuku and Termux, section 13). It refuses private apps.\n\nOnly text (or the screenshot you asked for) goes to OpenRouter.");

  sec("10. Modes",
   "Say 'focus mode', 'hacker mode', 'study mode', 'game mode' or 'chill mode'. 'mode' shows the current one.\n\n- Focus: red, very short answers, quiet, notifications muted and do not disturb on.\n- Hacker: dark with a green glow, technical answers.\n- Study: blue with glasses and a cap, teaches step by step.\n- Game: yellow with a controller hat, quiet, and it hides while a game is on screen.\n- Chill: the normal playful slime.");

  sec("11. Growing up",
   "The slime grows from real use, not keyword spam. XP sources: chatting (capped per day), voice messages it actually heard, phone tasks and screenshots it really completed, a daily streak bonus, and a care bonus when its needs are healthy at the first chat of the day. Repeating the same message earns nothing, and each topic bonus and every source has a daily cap, so farming does not work. Earned XP is never taken away.\n\nEight tiers: baby slime, slimelet, slime cadet, slime knight, slime king, slime sage, slime archon and celestial slime. From level 6 it visibly changes form - a sage aura at 6, a guardian shield at 7 and orbiting stars at 8. The crown arrives at level 5.\n\nAccessories: glasses after 25 coding chats, a grad cap after 15 math or 20 study chats, floating math symbols with the cap, headphones after 12 music chats, sparkles after 8 'fixed it' chats. Fourteen achievements track real behaviour (voice, tasks, screenshots, streaks, tiers) and announce themselves when unlocked - say 'achievements'. A birth date and daily streak are kept, every level-up is dated in the history, and 'evolution' shows all of it.");

  sec("12. Music, humming and notifications",
   "When music is playing it sometimes hums along with a little tune, a moving mouth and floating notes. 'hum' makes it hum now, 'hum off' stops it. It makes up its own tunes and never copies real lyrics.\n\nNotifications: it shows a short bubble when a new one arrives and flags urgent ones. 'catch me up' summarises what you missed. 'pings off' and 'pings on' control the bubbles. 'shh' keeps it quiet for 2 hours.");

  sec("13. Phone control with Shizuku and Termux",
   "Shizuku lets apps run commands with the power of a computer connected by adb. Termux is the terminal app that carries those commands.\n\nOne-time setup:\n1. Install Termux and Shizuku. Start Shizuku (it needs wireless debugging) and allow it.\n2. In the Shizuku app tap 'Use Shizuku in terminal apps' and export the two files (rish and rish_shizuku.dex) to your Download folder.\n3. In Termux run: termux-setup-storage (allow it).\n4. Run setup_rish.sh in Termux with: bash ~/setup_rish.sh. If it ends with '[ok] Shizuku shell works', you are done.\n5. In the slime chat, type 'shizuku' to test.\n\nThen you can say things like 'swipe up', 'tap 500 900', 'back', 'home', 'launch whatsapp', 'brightness 40', 'wifi off', 'shot' and 'look what is this?'. The Commands screen lists everything.\n\nSafety: the AI may suggest a phone action, but it always waits for your 'yes'. Only you can use 'sh' and 'term'.\n\nShizuku stops when you restart the phone (without root). Open Shizuku and start it again.");

  sec("14. Keeping Termux reachable",
   "The Termux commands need Termux to be allowed to run in the background. Phone makers often kill it. Do these three things:\n\n1. In Termux run these lines (once):\nmkdir -p ~/.termux/boot\nprintf '#!/data/data/com.termux/files/usr/bin/sh\\ntermux-wake-lock\\n' > ~/.termux/boot/slime.sh\nchmod +x ~/.termux/boot/slime.sh\ntermux-wake-lock\nThen install Termux:Boot (from the same place you got Termux) and open it once. The wake lock keeps Termux alive; you will see its notification.\n\n2. In phone settings open Termux's app info (the home screen has a button) and set Battery to unrestricted. If your phone has an Autostart list, switch Termux and Shizuku on. Lock Termux in the recent apps if your phone allows.\n\n3. In the slime chat type 'fix termux'. It uses Shizuku to exempt Termux, Shizuku and SlimeDroid from battery limits.\n\nIf a command says 'Termux didn't answer', type 'diagnose'. It checks everything and gives the exact fix.");

  sec("15. Files: hold, drop, stash",
   "'hold report.pdf' makes the slime pick up a file (it finds it in Download, Documents, Pictures, DCIM, Movies and Music). A little file shows by its hand and it gets chubby.\n\n- 'what are you holding' lists the files.\n- 'drop' puts them in Downloads. 'drop to documents', 'drop to pictures', 'drop to termux' or 'drop to /sdcard/SomeFolder' choose another place.\n- 'stash' puts what it carries away in /sdcard/SlimePouch/stash.\n\nIt copies the files, so the originals stay where they were. This needs Shizuku and Termux.");

  sec("16. If something goes wrong",
   "The slime is missing: open this app and tap 'Start slime'. It comes back to the middle of the screen.\n\nCommands fail or say 'Termux didn't answer': type 'diagnose'. Check Shizuku is running and read section 14.\n\n'too many messages today': you used the free limit. Wait for tomorrow, add another key, or add credit.\n\nReplies feel odd or change style: the free router picks a different model each time. Pin one with 'model NAME'.\n\nMath shows as plain text: it needs internet the first time.\n\nThe keyboard hides the box: tap the box once more; the chat jumps to the top while you type.\n\nListening won't start: check the microphone tick on the home screen, say 'listen status', and make sure the phone has a speech recognizer (Google speech services or an equivalent). The listening notification is required by Android while the mic is active.\n\nThe cloud voice fails: it falls back to the local engine automatically; 'tts mode local' forces offline speech, and 'tts engines' picks an installed engine.\n\nSomething else: type 'help' for the commands screen, 'status' for numbers, or 'diagnose' for a check-up.");

  sec("17. Privacy and safety in one page",
   "- Your memories, key list and files live on your phone.\n- Messages, relevant memories and, if you ask or allow peeks, screen text go to OpenRouter and the free model behind it.\n- Private-looking apps are skipped for peeks and 'look'.\n- Passwords, codes and card numbers are never saved to memory.\n- The AI can never run phone commands on its own: a short list of safe actions, and only after you say yes.\n- Anything dangerous (sh, term, settings, grant) only runs when you type it yourself.\n- Revoke an old API key at openrouter.ai/keys if you ever share it by mistake.");

  sec("18. Words explained",
   "Overlay: something drawn on top of other apps.\nAccessibility: an Android feature that lets an app read the screen and press things.\nShizuku: an app that gives other apps adb-level power.\nTermux: a terminal app for Android.\nrish: the Shizuku shell inside Termux.\nOpenRouter: a website that gives access to many AI models, some of them free.\nFree router: the model name 'openrouter/free', which picks a free model for you.\nLaTeX: the way math is written, like $x^2$.\nXP: experience points the slime earns as you chat.");

  sec("19. Talking and listening",
   "Speaking back: the slime has two kinds of voice. Cloud voices are natural neural voices (free, no key) that download short MP3 clips, so they need internet. Two cloud providers are tried in order: StreamElements (named voices like Brian or Amy) and Google's keyless Translate voice, which also supports Swahili via 'tts language sw'. If every cloud provider fails, the local voice (a speech engine already on your phone, works offline) takes over, and the slime says why once. Default mode is auto; 'tts provider google' pins the Google voice and 'tts provider streamelements' pins the named voices. Switch with 'tts mode cloud', 'tts mode local' or 'tts mode auto', try 'tts test', and use 'tts status' plus 'tts cloud test' to see exactly what works. 'tts cloud voices' lists neural voices (for example 'tts cloud voice Amy'); 'tts engines' and 'voice list' manage offline engines. The TTS button in chat turns spoken replies on and off.\n\nListening: tap the Mic button for one spoken message, or say 'listen on' for hands-free mode. Recognition runs on the phone through Android's speech services - no API key and no extra cost. It only listens while the screen is on; the mic switches off when the screen turns off and back on when it returns. While listening, Android shows an ongoing 'SlimeDroid is listening' notification, and the slime pauses its ear while it is speaking so it never hears itself. 'listen off' stops it, 'listen language sw' switches recognition to Swahili (sw-KE) and 'listen language en' back to English. If it ever seems deaf, say 'listen test': it narrates each step (ear opened, voice heard, mic level, recognized text) and prints the engine, Google-app presence and recent error codes so the exact failure is visible; 'listen engine ondevice' forces the offline recognizer on Android 12+ when the regular one keeps failing. Spoken words take the exact same path as typed ones, including commands. Both a single Mic tap and continuous mode run a microphone foreground service, and any recognizer error is shown in chat with its meaning (also visible via 'listen status'). If the phone has no speech recognizer the slime will say so instead of failing silently.");

  sec("20. The offline brain (no internet needed)",
   "SlimeDroid can run its chat fully on your phone through llama.cpp inside Termux - no account, no key, no quota, and it works in airplane mode. It is meant for short, direct conversations; cloud Gemini/OpenRouter remain the daily drivers for quality, Swahili and screenshots.\n\n32-bit phones (ABI armeabi-v7a only, for example the Tecno Spark 8C Go edition) cannot run llama.cpp: the Termux package and Google's supported Android ABI are arm64-only, and the 32-bit address space can't map the tensors. On those phones the app says so plainly and the AI button skips offline; use this on a 64-bit device such as the Modio M38 tablet instead.\n\nSetup (once; Wi-Fi recommended to protect data bundles, but mobile data works):\n- Say 'offline download smol' to get SmolLM2-360M (~390 MB, the fast default for 2 GB phones), or 'offline download qwen' for Qwen3-0.6B (~470 MB, a bit smarter and better at Swahili). 'offline download all' gets both. The first download also installs llama.cpp via Termux's package manager, and it runs headless in the background. Downloads are resumable - if mobile data drops, run the same command again and it continues from the partial file. 'offline status' shows the install phase, partial-file size, real curl/server state, free RAM and disk; you can also check directly in Termux with 'ls -la ~/slimemodels' and 'cat ~/slimemodels/dl.log'.\n- When it's done, say 'use offline' or tap the AI button until it shows 'AI: Offline' (purple). Your first message loads the model for about 10-20 seconds ('loading my brain...'), after which replies stream word by word; the server keeps running until you switch back to a cloud provider, say 'offline stop', or close the slime.\n\nHow it works: a tiny llama-server listens only on 127.0.0.1:8080 inside the phone, so nothing ever leaves the device. The app takes a Termux wake lock while it runs and releases it on stop, and the models live in Termux's home folder (~/slimemodels). Context is capped at 1024 tokens with four CPU threads, which is why answers are kept short. The small models can't reliably use the memory/action tag features, so tag extraction, self-initiated phone actions and screen peeks stay cloud-only; 'look' screenshots automatically fall back to whichever cloud keys you have. Expect English to be decent, Swahili/Sheng basic.");

  sec("21. Reminders, briefing, live search, photo math and routines",
   "Five extras that all work with the free setup you already have.\n\nReminders: 'remind me in 20 minutes to call mum' or 'remind me tomorrow 7am to charge my power bank'. The slime fires a bubble (and speaks if TTS is on) at the time, even after a reboot; 'reminders' lists them and 'forget reminder N' removes one. Exact alarms are used when the system allows, otherwise the alarm still fires slightly late.\n\nMorning briefing: 'briefing 7am' schedules a daily spoken rundown - greeting, weather, unread pings, your level and streak, and any pet needs. 'briefing now' previews it, 'briefing off' stops it. Weather comes from Open-Meteo and needs no API key; 'weather' asks for current conditions and 'weather city Mombasa' changes the city (default Nairobi).\n\nLive search: 'search who won the match last night' (or 'google ...') asks Gemini with Google Search grounding, so answers use current web facts instead of the model's built-in cutoff. It needs a Gemini key and shares the flash-lite free pool; if a project can't use the search tool it answers without it.\n\nPhoto math: open a problem on screen and say 'photo math' (or 'solve this'). The slime screenshots it and gets the vision model to show every step and the final answer. It needs the same Shizuku/Termux setup as 'look'.\n\nRoutines: your own if-this-then-that rules. Examples: 'when I open tiktok then shh', 'when charging then brightness 20', 'when headphones connect then tts off', 'when I unlock then say good morning'. Triggers are foreground app changes, charging, unplugging, headphones connecting/disconnecting and unlocking; the action is any normal slime command. 'routines' lists them and 'forget routine N' deletes one. Each rule runs at most once per 30 seconds.");

  sec("22. About and contacting the creator",
   "SlimeDroid is free and open source, created by heavens assunder, and built entirely in Termux with no paid APIs - everything it does runs on free tiers or on the phone itself.\n\nContact or follow the project:\n- WhatsApp: +254 769 204848, or open wa.me/254769204848 (there is a green WhatsApp button at the bottom of the home screen).\n- GitHub repository: github.com/heavensassunder/floatingpet - all the source code, the Termux build script and issue reports live there.\n- In chat, say 'about' to see the links as tappable text.");

  setContentView(sv);
 }
 TextView text(String s,float size,String color,boolean bold,int topDp){
  TextView t=new TextView(this); t.setText(s); t.setTextSize(size); t.setTextColor(Color.parseColor(color));
  if(bold) t.setTypeface(Typeface.DEFAULT_BOLD);
  t.setPadding(0,(int)(topDp*d),0,(int)(2*d)); col.addView(t); return t;
 }
 Button btn(String label,final boolean open){
  Button b=new Button(this); b.setText(label); b.setAllCaps(false); b.setTextSize(12f); b.setTextColor(Color.WHITE);
  GradientDrawable g=new GradientDrawable(); g.setColor(Color.parseColor("#5DADE2")); g.setCornerRadius(12*d); b.setBackground(g);
  b.setPadding((int)(14*d),(int)(6*d),(int)(14*d),(int)(6*d));
  LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT); lp.setMargins(0,(int)(8*d),(int)(8*d),0); b.setLayoutParams(lp);
  b.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ for(int i=0;i<bodies.size();i++) setOpen(i,open); }});
  return b;
 }
 void setOpen(int i,boolean open){
  bodies.get(i).setVisibility(open?View.VISIBLE:View.GONE);
  heads.get(i).setText((open?"-  ":"+  ")+titles.get(i).getText());
 }
 void sec(String title,String body){
  final TextView h=new TextView(this); h.setTextSize(15f); h.setTypeface(Typeface.DEFAULT_BOLD); h.setTextColor(Color.parseColor("#5DADE2"));
  h.setPadding(0,(int)(16*d),0,(int)(4*d));
  final TextView t=new TextView(this); t.setText(title);
  final TextView b=new TextView(this); b.setText(body); b.setTextSize(13f); b.setTextColor(Color.parseColor("#E5E8E8")); b.setLineSpacing(0f,1.15f);
  b.setPadding(0,0,0,(int)(6*d));
  heads.add(h); bodies.add(b); titles.add(t);
  final int idx=heads.size()-1;
  col.addView(h); col.addView(b);
  setOpen(idx,false);
  h.setOnClickListener(new View.OnClickListener(){ public void onClick(View v){ setOpen(idx,bodies.get(idx).getVisibility()!=View.VISIBLE); }});
 }
}
